// @name Steps
// @background #18181b
// @refresh 3600
// Tabs: a tap picks one, and the panel under them changes.
const tabs = ['Today', 'Week', 'Month']
let active = 0

// The tab outlives the render: a board may start each render with a fresh
// module, and a frame rendered on its server does, at every tap.
const show = (i) => {
  active = i
  frameos.remember('tab', active)
}

const steps = [6.2, 8.4, 4.1, 9.8, 7.3, 11.2, 5.6]
const days = ['M', 'T', 'W', 'T', 'F', 'S', 'S']

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// The month's days by how far they got: a shade of green in color, a box
// filled that far up in high contrast.
const THEMES = {
  color: {
    page: 'bg-zinc-900 text-white',
    bar: 'p-4 border-b border-white/10',
    barSmall: 'p-2 border-b border-white/10',
    tab: 'text-zinc-400 active:bg-white/10',
    tabOn: 'bg-white text-zinc-900 font-semibold',
    muted: 'text-zinc-400',
    dim: 'text-zinc-500',
    day: 'text-zinc-300',
    track: 'bg-white/10',
    fill: 'bg-lime-400',
    column: 'bg-lime-400/40',
    columnOn: 'bg-lime-400',
    cells: ['bg-lime-400', 'bg-lime-400/60', 'bg-lime-400/30', 'bg-zinc-800'],
    cellText: ['text-zinc-900', 'text-zinc-900', 'text-white', 'text-zinc-300'],
    filled: [],
  },
  high: {
    page: 'bg-white text-black',
    bar: 'px-4 pt-4 pb-[15px] border-b-2 border-black',
    barSmall: 'px-2 pt-2 pb-[7px] border-b-2 border-black',
    tab: 'text-black',
    tabOn: 'bg-black text-white font-semibold',
    muted: 'text-black',
    dim: 'text-black',
    day: 'text-black',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    column: 'bg-white border-2 border-black',
    columnOn: 'bg-black',
    cells: ['bg-black', 'flex flex-col justify-end border-2 border-black', 'flex flex-col justify-end border-2 border-black', 'border-2 border-black'],
    cellText: ['text-white', 'text-black', 'text-black', 'text-black'],
    filled: ['', 'h-[60%]', 'h-[30%]', ''],
    fillColor: 'bg-black',
  },
}

// Colour e-paper (Spectra's six inks): the high-contrast look with the
// progress in solid green ink, as the panel shows it.
THEMES.inks = {
  ...THEMES.high,
  fill: 'bg-[#2a5531]',
  columnOn: 'bg-[#2a5531]',
  cells: ['bg-[#2a5531]', ...THEMES.high.cells.slice(1)],
  fillColor: 'bg-[#2a5531]',
}

const themeOf = (app) => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

// What each shade of the month means: at the goal, most of the way, some, a
// little.
const LEVELS = ['10k+', '6k+', '3k+', 'less']

// `k`: how much larger than at 480 px everything is (2 on a 13.3" e-paper at
// render scale 1, 1 elsewhere: a bigger screen is made larger by its scale).
const Today = ({ t, small, track, k }) => (
  <div className={`flex flex-col items-center justify-center h-full gap-[${(small ? 4 : 8) * k}px]`}>
    <span className={`text-[${(small ? 60 : 96) * k}px] leading-none font-bold`}>7,341</span>
    <span className={`text-[${(small ? 16 : 20) * k}px] ${t.muted}`}>steps so far today</span>
    <div className={`w-[${track}px] h-[${12 * k}px] rounded-full mt-[${(small ? 8 : 16) * k}px] ${t.track}`}>
      <div className={`h-full w-[73%] rounded-full ${t.fill}`} />
    </div>
    <span className={`text-[${(small ? 14 : 16) * k}px] ${t.muted}`}>73% of 10,000</span>
  </div>
)

const Week = ({ t, small, k }) => (
  <div className={`flex items-end gap-[${(small ? 4 : 12) * k}px] h-full`}>
    {steps.map((n, i) => (
      <div className={`flex-1 flex flex-col items-center gap-[${(small ? 4 : 8) * k}px] h-full justify-end`}>
        <span className={`text-[${(small ? 12 : 14) * k}px] ${t.muted}`}>{`${n}k`}</span>
        <div className={`w-full rounded-t-lg ${i === 5 ? t.columnOn : t.column} h-[${Math.round(n * 6.5)}%]`} />
        <span className={`text-[${16 * k}px] ${t.day}`}>{days[i]}</span>
      </div>
    ))}
  </div>
)

// Four weeks of days, each `cell` px tall, under the weekdays' letters: each
// day's date in its box, and a key to the shades under them.
const Month = ({ t, small, cell, k }) => {
  const label = `text-[${(small ? 12 : 14) * k}px]`
  const gap = `gap-[${(small ? 4 : 8) * k}px]`
  return (
    <div className={`flex flex-col ${gap} h-full`}>
      <div className={`grid grid-cols-7 ${gap}`}>
        {days.map((d) => <span className={`text-center ${label} ${t.day}`}>{d}</span>)}
      </div>
      <div className={`grid grid-cols-7 ${gap}`}>
        {Array.from({ length: 28 }).map((_, i) => {
          const level = (i * 7 + 3) % 4
          return (
            <div className={`relative h-[${cell}px] rounded-md ${t.cells[level]}`}>
              {t.filled[level] ? <div className={`w-full rounded-b ${t.fillColor} ${t.filled[level]}`} /> : null}
              {cell >= 16 ? (
                <span className={`absolute left-[${(small ? 4 : 8) * k}px] top-[${(small ? 3 : 6) * k}px] ${label} leading-none ${t.cellText[level]} ${t.filled[level] ? 'bg-white px-[2px]' : ''}`}>{String(i + 1)}</span>
              ) : null}
            </div>
          )
        })}
      </div>
      <div className={`flex items-center flex-wrap gap-x-[${(small ? 8 : 16) * k}px] ${label} ${t.muted}`}>
        {LEVELS.map((name, level) => (
          <div className={`flex items-center gap-[${4 * k}px]`}>
            <div className={`w-[${(small ? 12 : 16) * k}px] h-[${(small ? 12 : 16) * k}px] rounded-sm ${t.cells[level]}`} />
            <span>{name}</span>
          </div>
        ))}
        {small ? null : <span className="flex-1 text-right">7 of 28 days at the goal</span>}
      </div>
    </div>
  )
}

// On a round panel the rim is the chart: today's progress as a ring, the
// week as seven arcs, the month as 28 days around the dial; the numbers in
// the middle, the tabs in the arc below.
const RIM = {
  color: { track: 'rgba(255,255,255,0.10)', fill: '#a3e635', levels: ['#a3e635', 'rgba(163,230,53,0.6)', 'rgba(163,230,53,0.3)', '#27272a'] },
  high: { track: '#d4d4d4', fill: '#000000', levels: ['#000000', '#525252', '#a3a3a3', '#e5e5e5'] },
}
// An arc of the circle (cx, cy, r) from a to b, in turns clockwise from the top.
const arc = (cx, cy, r, a, b) => {
  const p = (f) => `${(cx + r * Math.sin(f * 2 * Math.PI)).toFixed(1)} ${(cy - r * Math.cos(f * 2 * Math.PI)).toFixed(1)}`
  return `M ${p(a)} A ${r} ${r} 0 ${b - a > 0.5 ? 1 : 0} 1 ${p(b)}`
}

const getRound = (app, context, high) => {
  const t = high ? THEMES.high : THEMES.color
  const rim = high ? RIM.high : RIM.color
  const W = context.imageWidth, H = context.imageHeight
  const size = Math.min(W, H), r = size / 2
  const k = r / 240
  const px = (n) => Math.max(1, Math.round(n * k))
  const text = (n) => Math.max(14, px(n))
  const stroke = px(18)
  const ringR = r - Math.max(12, px(14)) - stroke / 2
  const box = (cy, h, w) => `absolute left-[${Math.round((size - w) / 2)}px] top-[${Math.round(r + cy - h / 2)}px] w-[${Math.round(w)}px] h-[${Math.round(h)}px] flex flex-col items-center justify-center`
  let paths, middle, labels = null
  if (active === 0) {
    paths = [
      <path d={arc(r, r, ringR, 0, 0.9999)} stroke={rim.track} strokeWidth={stroke} fill="none" />,
      <path d={arc(r, r, ringR, 0, 0.73)} stroke={rim.fill} strokeWidth={stroke} fill="none" strokeLinecap="round" />,
    ]
    middle = (
      <div className={box(-r * 0.1, r * 0.9, r * 1.5)}>
        <span className={`text-[${px(80)}px] leading-none font-bold`}>7,341</span>
        <span className={`text-[${text(20)}px] mt-[${px(8)}px] ${t.muted}`}>steps so far today</span>
        <span className={`text-[${text(14)}px] ${t.dim}`}>73% of 10,000</span>
      </div>
    )
  } else if (active === 1) {
    // Seven arcs, as long as each day got; the highest day fills its seventh.
    const top = Math.max(...steps)
    paths = steps.map((n, i) => {
      const a = i / 7 + 0.006, span = 1 / 7 - 0.012
      return [
        <path d={arc(r, r, ringR, a, a + span)} stroke={rim.track} strokeWidth={stroke} fill="none" />,
        <path d={arc(r, r, ringR, a, a + span * (n / top))} stroke={i === 5 ? rim.fill : rim.levels[1]} strokeWidth={stroke} fill="none" />,
      ]
    })
    middle = (
      <div className={box(-r * 0.1, r * 0.9, r * 1.5)}>
        <span className={`text-[${px(72)}px] leading-none font-bold`}>{`${steps.reduce((a, b) => a + b, 0).toFixed(1)}k`}</span>
        <span className={`text-[${text(20)}px] mt-[${px(8)}px] ${t.muted}`}>steps this week</span>
        <span className={`text-[${text(14)}px] ${t.dim}`}>{`best: Saturday, ${steps[5]}k`}</span>
      </div>
    )
    // Each day's letter inside its arc's middle.
    const labelR = ringR - stroke / 2 - text(15)
    labels = days.map((d, i) => {
      const f = (i + 0.5) / 7 * 2 * Math.PI
      const x = r + labelR * Math.sin(f), y = r - labelR * Math.cos(f)
      return (
        <div className={`absolute left-[${Math.round(x - 15)}px] top-[${Math.round(y - 12)}px] w-[30px] h-[24px] flex items-center justify-center text-[${text(15)}px] ${t.day}`}>{d}</div>
      )
    })
  } else {
    paths = Array.from({ length: 28 }).map((_, i) => {
      const a = i / 28 + 0.004
      return <path d={arc(r, r, ringR, a, a + 1 / 28 - 0.008)} stroke={rim.levels[(i * 7 + 3) % 4]} strokeWidth={stroke} fill="none" />
    })
    middle = (
      <div className={box(-r * 0.1, r * 0.9, r * 1.5)}>
        <span className={`text-[${px(72)}px] leading-none font-bold`}>7 of 28</span>
        <span className={`text-[${text(20)}px] mt-[${px(8)}px] ${t.muted}`}>days at the goal</span>
        <span className={`text-[${text(14)}px] ${t.dim}`}>each day around the dial</span>
      </div>
    )
  }
  // The tabs' chord inside the ring and the week's letters.
  const innerR = ringR - stroke / 2 - text(15) * 2
  const tabsW = Math.round(2 * Math.sqrt(innerR * innerR - (r * 0.56) ** 2))
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${(W - size) >> 1}px] top-[${(H - size) >> 1}px] w-[${size}px] h-[${size}px]`}>
        <svg className={`absolute left-0 top-0 w-[${size}px] h-[${size}px]`} viewBox={`0 0 ${size} ${size}`}>{paths}</svg>
        <div className={box(-r * 0.58, px(28), r)}>
          <span className={`text-[${text(16)}px] uppercase font-semibold ${t.dim}`}>Steps</span>
        </div>
        {middle}
        {labels}
        <div className={box(r * 0.5, px(44), tabsW)}>
          <div className="flex items-center justify-center gap-1 w-full">
            {tabs.map((tab, i) => (
              <div className={`flex-1 flex items-center justify-center h-[${px(40)}px] rounded-lg text-[${text(16)}px] ${i === active ? t.tabOn : t.tab}`}
                onClick={() => show(i)}>{tab}</div>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}

// The frame's Back on the week or the month goes back to today, as a tap on
// its tab does; on today it is the frame's.
export function onEvent(app, context) {
  if (context.event !== 'back') return false
  active = frameos.recall('tab') ?? active
  if (!active) return false
  show(0)
  return true
}

export function get(app, context) {
  active = frameos.recall('tab') ?? active
  if (context?.round === true) return getRound(app, context, highContrast(app))
  const t = themeOf(app)
  // A small screen (a watch, a 2.8" panel, a short strip): the same, smaller.
  // At full size it needs about 400 x 360 px.
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const small = W < 400 || H < 360
  // A panel of 900 px or more on its shorter side at render scale 1 (a 13.3"
  // colour e-paper, 1200 px) as much larger as it is, by halves, so the whole
  // panel is used.
  const k = Math.min(W, H) >= 900 ? Math.min(3, Math.floor((Math.min(W, H) / 480) * 2) / 2) : 1
  const bar = (small ? 48 : 69) * k // the tab bar's height, its border in
  const pad = (small ? 12 : 24) * k
  // The month's rows share what the weekdays' letters and the key leave, as
  // tall as a day's box is wide at most.
  const gap = (small ? 4 : 8) * k
  const label = (small ? 16 : 20) * k // the weekdays' and the key's lines
  const wide = Math.floor((W - 2 * pad - 6 * gap) / 7)
  const cell = Math.max(12, Math.min(wide, Math.floor((H - bar - 2 * pad - 2 * label - 5 * gap) / 4)))
  return (
    <div className={`flex flex-col ${t.page}`}>
      <div className={`flex items-center gap-[${(small ? 4 : 8) * k}px] ${k > 1 ? `px-[${16 * k}px] py-[${16 * k}px] border-b-${Math.round(2 * k)} ${t === THEMES.color ? 'border-white/10' : 'border-black'}` : small ? t.barSmall : t.bar}`}>
        {tabs.map((tab, i) => (
          <div className={`px-[${(small ? 12 : 20) * k}px] py-[${(small ? 4 : 8) * k}px] text-[${(small ? 16 : 18) * k}px] rounded-lg ${i === active ? t.tabOn : t.tab}`}
            onClick={() => show(i)}>{tab}</div>
        ))}
        {W < 300 ? null : <span className={`flex-1 text-right text-[${(small ? 16 : 18) * k}px] font-semibold ${t.muted}`}>Steps</span>}
      </div>
      <div className={`flex-1 min-h-0 p-[${pad}px]`}>
        {[<Today t={t} small={small} track={Math.min(256 * k, W - 2 * pad)} k={k} />, <Week t={t} small={small} k={k} />, <Month t={t} small={small} cell={cell} k={k} />][active]}
      </div>
    </div>
  )
}
